CREATE TABLE category (category_id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255) NOT NULL);
CREATE TABLE book (book_id BIGINT AUTO_INCREMENT PRIMARY KEY, category_id BIGINT NOT NULL, title VARCHAR(100) NOT NULL, description TEXT, is_available BOOLEAN NOT NULL DEFAULT TRUE, FOREIGN KEY (category_id) REFERENCES category(category_id));
CREATE TABLE member (member_id BIGINT AUTO_INCREMENT PRIMARY KEY, email VARCHAR(254) NOT NULL UNIQUE, password VARCHAR(60) NOT NULL, nickname VARCHAR(50) NOT NULL UNIQUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE rating (rating_id BIGINT AUTO_INCREMENT PRIMARY KEY, member_id BIGINT NOT NULL, movie_id BIGINT NOT NULL, score TINYINT NOT NULL, comment TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (member_id) REFERENCES member(member_id), CONSTRAINT uk_rating_member_movie UNIQUE (member_id, movie_id));
CREATE TABLE favorite (favorite_id BIGINT AUTO_INCREMENT PRIMARY KEY, member_id BIGINT NOT NULL, movie_id BIGINT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (member_id) REFERENCES member(member_id), CONSTRAINT uk_favorite_member_movie UNIQUE (member_id, movie_id));
